560	/// One fully-aggregated model turn.
561	///
562	/// Reassembled from a [`ModelEvent`] stream by [`ModelTurnAccumulator`]: the
563	/// concatenated text/reasoning deltas become at most one
564	/// [`crate::Item::AssistantMessage`]. Provider data alone also creates that
565	/// message. Each distinct `ToolCallDelta` `call_id` becomes one
566	/// [`crate::Item::ToolCall`], `usage` is the last `Usage` snapshot observed,
567	/// and `finish_reason` is the terminal `Finish` reason.
568	/// Two or more blank-id calls make [`ModelTurnAccumulator::finish`] fail
569	/// instead of producing items.
570	#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
571	#[non_exhaustive]
572	pub struct ModelTurn {
573	    /// Reconstructed items: an optional leading `AssistantMessage` (text,
574	    /// reasoning and/or provider data content, in that order) followed by
575	    /// zero or more `ToolCall`s, in deterministic `call_id`-sorted order.
576	    pub items: Vec<crate::Item>,
577	    /// The last [`ModelEvent::Usage`] snapshot observed (last-wins; usage
578	    /// snapshots are never summed within a turn), or the zero default if
579	    /// the stream never emitted one.
580	    pub usage: crate::TokenUsage,
581	    /// Why the response ended.
582	    pub finish_reason: FinishReason,
583	}
584	
585	impl ModelTurn {
586	    /// Construct a `ModelTurn` directly from its parts.
587	    ///
588	    /// The normal path is [`ModelTurnAccumulator::finish`], which reassembles
589	    /// a turn from a live [`ModelEvent`] stream. This constructor is for
590	    /// callers that already have `items`/`usage`/`finish_reason` in hand —
591	    /// durable-runner activities that reconstruct a turn from a stored
592	    /// result, and tests — and would otherwise be unable to build one at all
593	    /// (`#[non_exhaustive]` blocks struct-literal construction outside this
594	    /// crate).
595	    pub fn new(
596	        items: Vec<crate::Item>,
597	        usage: crate::TokenUsage,
598	        finish_reason: FinishReason,
599	    ) -> Self {
600	        Self {
601	            items,
602	            usage,
603	            finish_reason,
604	        }
605	    }
606	}
607	
608	/// Accumulates the in-progress tool call across `ModelEvent::ToolCallDelta`
609	/// chunks for one `call_id`.
610	#[derive(Debug, Default)]
611	struct ToolCallAccum {
612	    name: Option<String>,
613	    args_str: String,
614	}
615	
616	/// Reassemble streamed model output into [`crate::Item`]s.
617	fn build_items(
618	    agent_name: &str,
619	    text: String,
620	    reasoning: String,
621	    provider_data: Vec<crate::ContentPart>,
622	    tool_accum: std::collections::BTreeMap<String, ToolCallAccum>,
623	) -> Result<Vec<crate::Item>, String> {
624	    let mut items = Vec::new();
625	    if !text.is_empty() || !reasoning.is_empty() || !provider_data.is_empty() {
626	        let mut content = Vec::new();
627	        if !reasoning.is_empty() {
628	            content.push(crate::ContentPart::Reasoning { text: reasoning });
629	        }
630	        if !text.is_empty() {
631	            content.push(crate::ContentPart::Text { text });
632	        }
633	        content.extend(provider_data);
634	        items.push(crate::Item::AssistantMessage {
635	            content,
636	            agent: Some(agent_name.to_owned()),
637	        });
638	    }
639	    for (call_id, accum) in tool_accum {
640	        // OpenAI streaming legitimately emits an empty `arguments` delta for
641	        // zero-parameter tool calls — normalize blank/whitespace-only args to
642	        // `{}` rather than failing the whole turn on a `serde_json` EOF error.
643	        let args_str = if accum.args_str.trim().is_empty() {
644	            "{}"
645	        } else {
646	            accum.args_str.as_str()
647	        };
648	        let args = serde_json::from_str(args_str).map_err(|e| {
649	            format!(
650	                "invalid tool args for call_id={call_id} (name={}): {e}",
651	                accum.name.as_deref().unwrap_or("?")
652	            )
653	        })?;
654	        items.push(crate::Item::ToolCall {
655	            call_id,
656	            name: accum.name.unwrap_or_default(),
657	            args,
658	        });
659	    }
660	    Ok(items)
661	}
662	
663	/// Accumulates a streamed model response into a [`ModelTurn`].
664	///
665	/// Feed every successful [`ModelEvent`] from a [`Model::invoke`] stream via
666	/// [`Self::observe`], then call [`Self::finish`] once the stream ends (after
667	/// observing a `Finish` event) to reassemble the turn's [`crate::Item`]s.
668	#[derive(Debug)]
669	pub struct ModelTurnAccumulator {
670	    agent_name: String,
671	    text: String,
672	    reasoning: String,
673	    provider_data: Vec<crate::ContentPart>,
674	    tool_accum: std::collections::BTreeMap<String, ToolCallAccum>,
675	    /// Names carried by deltas under a blank `call_id`, in arrival order.
676	    blank_names: Vec<String>,
677	    finish_reason: FinishReason,
678	    latest_usage: Option<crate::TokenUsage>,
679	}
680	
681	impl ModelTurnAccumulator {
682	    /// Start a new accumulator. `agent_name` is attributed to the
683	    /// resulting turn's `AssistantMessage`, if any.
684	    pub fn new(agent_name: impl Into<String>) -> Self {
685	        Self {
686	            agent_name: agent_name.into(),
687	            text: String::new(),
688	            reasoning: String::new(),
689	            provider_data: Vec::new(),
690	            tool_accum: std::collections::BTreeMap::new(),
691	            blank_names: Vec::new(),
692	            finish_reason: FinishReason::Stop,
693	            latest_usage: None,
694	        }
695	    }
696	
697	    /// Feed one successful model event. `Err(ModelEvent)`s are the caller's
698	    /// concern — this only observes `Ok` events from the stream.
699	    pub fn observe(&mut self, event: &ModelEvent) {
700	        match event {
701	            ModelEvent::TokenDelta { text } => self.text.push_str(text),
702	            ModelEvent::ReasoningDelta { text } => self.reasoning.push_str(text),
703	            ModelEvent::ToolCallDelta {
704	                call_id,
705	                name,
706	                args_delta,
707	            } => {
708	                if call_id.is_empty() {
709	                    if let Some(n) = name {
710	                        self.blank_names.push(n.clone());
711	                    }
712	                }
713	                let a = self.tool_accum.entry(call_id.clone()).or_default();
714	                if a.name.is_none() {
715	                    if let Some(n) = name.as_deref() {
716	                        a.name = Some(n.to_owned());
717	                    }
718	                }
719	                a.args_str.push_str(args_delta);
720	            }
721	            ModelEvent::Usage {
722	                input_tokens,
723	                output_tokens,
724	                cached_input_tokens,
725	                reasoning_tokens,
726	            } => {
727	                self.latest_usage = Some(crate::TokenUsage {
728	                    input_tokens: u64::from(*input_tokens),
729	                    output_tokens: u64::from(*output_tokens),
730	                    cached_input_tokens: cached_input_tokens.map(u64::from).unwrap_or(0),
731	                    reasoning_tokens: reasoning_tokens.map(u64::from).unwrap_or(0),
732	                    total_tokens: u64::from(*input_tokens) + u64::from(*output_tokens),
733	                });
734	            }
735	            ModelEvent::Finish { reason } => {
736	                self.finish_reason = reason.clone();
737	            }
738	            ModelEvent::ProviderData {
739	                provider,
740	                call_id,
741	                data,
742	            } => self.provider_data.push(crate::ContentPart::ProviderData {
743	                provider: provider.clone(),
744	                call_id: call_id.clone(),
745	                data: data.clone(),
746	            }),
747	        }
748	    }
749	
750	    /// Reassemble. `Err(String)` = invalid JSON in accumulated tool-call
751	    /// args, **or** an ambiguous blank-id bucket (two or more name-carrying
752	    /// deltas under `""`), which is checked first, before any parse.
753	    pub fn finish(self) -> Result<ModelTurn, String> {
754	        if self.blank_names.len() >= 2 {
755	            let count = self.blank_names.len();
756	            let list = format_blank_names(&self.blank_names);
757	            tracing::warn!(
758	                target: "paigasus::core::model",
759	                count,
760	                names = %list,
761	                "refusing a model turn with parallel tool calls under a blank call_id"
762	            );
763	            return Err(format!(
764	                "ambiguous tool calls: {count} parallel tool calls arrived under a blank call_id (names: {list}); their arguments cannot be attributed to a call"
765	            ));
766	        }
767	        let items = build_items(
768	            &self.agent_name,
769	            self.text,
770	            self.reasoning,
771	            self.provider_data,
772	            self.tool_accum,
773	        )?;
774	        Ok(ModelTurn {
775	            items,
776	            usage: self.latest_usage.unwrap_or_default(),
777	            finish_reason: self.finish_reason,
778	        })
779	    }

