1	//! Translate Gemini SSE chunks into core `ModelEvent`s.
2	
3	use paigasus_helikon_core::{FinishReason, ModelError, ModelEvent};
4	
5	use crate::sse::GeminiChunk;
6	use crate::PROVIDER_DATA_KEY;
7	
8	/// Stateful translator from Gemini SSE chunks to core `ModelEvent`s.
9	pub(crate) struct StreamTranslator {
10	    fn_index: usize,
11	    call_index: usize,
12	    model_id: String,
13	    api: &'static str,
14	    saw_function_call: bool,
15	    finish_reason: Option<String>,
16	}
17	
18	impl StreamTranslator {
19	    pub(crate) fn new(model_id: String, api: &'static str) -> Self {
20	        Self {
21	            fn_index: 0,
22	            call_index: 0,
23	            model_id,
24	            api,
25	            saw_function_call: false,
26	            finish_reason: None,
27	        }
28	    }
29	
30	    pub(crate) fn consume(&mut self, chunk: GeminiChunk) -> Vec<Result<ModelEvent, ModelError>> {
31	        let mut out = Vec::new();
32	
33	        if let Some(pf) = &chunk.prompt_feedback {
34	            if let Some(reason) = &pf.block_reason {
35	                out.push(Err(ModelError::Refused {
36	                    reason: format!("prompt blocked: {reason}"),
37	                }));
38	                return out;
39	            }
40	        }
41	
42	        if let Some(cand) = chunk.candidates.into_iter().next() {
43	            if let Some(content) = cand.content {
44	                for part in content.parts {
45	                    if let Some(text) = part.text {
46	                        out.push(Ok(ModelEvent::TokenDelta { text }));
47	                    } else if let Some(fc) = part.function_call {
48	                        self.saw_function_call = true;
49	                        let call_id = fc.id.unwrap_or_else(|| {
50	                            let id = format!("fc_{}", self.fn_index);
51	                            self.fn_index += 1;
52	                            id
53	                        });
54	                        out.push(Ok(ModelEvent::ToolCallDelta {
55	                            call_id: call_id.clone(),
56	                            name: Some(fc.name),
57	                            args_delta: fc.args.to_string(),
58	                        }));
59	                        let index = self.call_index;
60	                        self.call_index += 1;
61	                        let sig = part.thought_signature.as_ref().and_then(|v| v.as_str());
62	                        let data = match sig {
63	                            Some(sig) => serde_json::json!({
64	                                "index": index,
65	                                "thoughtSignature": sig,
66	                                "model": self.model_id,
67	                                "api": self.api,
68	                            }),
69	                            None => serde_json::json!({ "index": index }),
70	                        };
71	                        out.push(Ok(ModelEvent::ProviderData {
72	                            provider: PROVIDER_DATA_KEY.to_owned(),
73	                            call_id: Some(call_id),
74	                            data,
75	                        }));
76	                    }
77	                }
78	            }
79	            if let Some(fr) = cand.finish_reason {
80	                self.finish_reason = Some(fr);
81	            }
82	        }
83	
84	        if let Some(u) = chunk.usage_metadata {
85	            out.push(Ok(ModelEvent::Usage {
86	                input_tokens: u.prompt_token_count,
87	                output_tokens: u.candidates_token_count,
88	                cached_input_tokens: u.cached_content_token_count,
89	                reasoning_tokens: u.thoughts_token_count,
90	            }));
91	        }
92	
93	        out
94	    }
95	
96	    /// Emit the terminal `Finish` — only when a `finishReason` was observed.
97	    pub(crate) fn finish(&mut self) -> Vec<Result<ModelEvent, ModelError>> {
98	        let Some(reason) = self.finish_reason.take() else {
99	            return Vec::new();
100	        };
101	        let fr = match reason.as_str() {
